# ============================================================================
# Tests: time-series operators l() / d() (Ticket F4, decision D8)
#
# Part 1: pure-R property tests (lag semantics, gaps, panels, errors,
#         option canonicalization, predict, collinearity).
# Part 2: Stata fixture comparisons — the 9 help-file examples that use ts
#         operators (help-file-specs.md H72-H76, H83-H85, H88), generated by
#         generate-ts-operator-fixtures.do.
# ============================================================================

data(phillips)
data(klein)
data(abdata)

# ============================================================================
# 1. Lag semantics (pure R)
# ============================================================================

test_that("l() equals a manual lag on consecutive time-series data", {
  manual <- phillips
  manual$unem_l1 <- c(NA, head(manual$unem, -1))
  fit_op <- ivreg2(cinf ~ 1 | unem | l(unem, 1), data = phillips,
                   tvar = "year")
  fit_manual <- ivreg2(cinf ~ 1 | unem | unem_l1, data = manual)
  expect_equal(unname(coef(fit_op)), unname(coef(fit_manual)))
  expect_equal(nobs(fit_op), nobs(fit_manual))
  expect_equal(nobs(fit_op), nrow(phillips) - 1L)
})

test_that("l() lags by time value, not row position (shuffled rows)", {
  shuffled <- phillips[sample(nrow(phillips)), ]
  fit_orig <- ivreg2(cinf ~ l(unem, 2), data = phillips, tvar = "year")
  fit_shuf <- ivreg2(cinf ~ l(unem, 2), data = shuffled, tvar = "year")
  expect_equal(coef(fit_orig), coef(fit_shuf))
  expect_equal(vcov(fit_orig), vcov(fit_shuf))
})

test_that("lag ranges expand to one term per lag with canonical names", {
  fit <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                tvar = "year")
  expect_identical(fit$instruments,
                   c("l(unem, 1)", "l(unem, 2)", "l(unem, 3)"))
  expect_equal(nobs(fit), nrow(phillips) - 3L)
})

test_that("l(x, 0) is x itself and triggers collinearity handling", {
  expect_warning(
    fit <- ivreg2(cinf ~ unem + l(unem, 0), data = phillips, tvar = "year"),
    "collinear"
  )
  expect_equal(length(coef(fit)), 2L)
})

test_that("d() is the iterated (Stata) difference, not fixest's distance-k", {
  ph <- phillips
  ph$d2_unem <- c(NA, NA, diff(diff(ph$unem)))
  fit_op <- ivreg2(cinf ~ d(unem, 2), data = ph, tvar = "year")
  fit_manual <- ivreg2(cinf ~ d2_unem, data = ph)
  expect_equal(unname(coef(fit_op)), unname(coef(fit_manual)))
  expect_equal(nobs(fit_op), nrow(ph) - 2L)
})

test_that("d() ranges expand like l() ranges", {
  fit <- ivreg2(cinf ~ d(unem, 1:2), data = phillips, tvar = "year")
  expect_true(all(c("d(unem, 1)", "d(unem, 2)") %in% names(coef(fit))))
})

test_that("operators work on expressions, and inside other functions", {
  ph <- phillips
  ph$exp_unem <- exp(ph$unem)
  fit_expr <- ivreg2(cinf ~ l(log(exp_unem), 1), data = ph, tvar = "year")
  fit_wrap <- ivreg2(cinf ~ log(exp(l(unem, 1))), data = ph, tvar = "year")
  fit_ref <- ivreg2(cinf ~ 1 + lag_ref,
                    data = transform(ph, lag_ref = c(NA, head(unem, -1))))
  expect_equal(unname(coef(fit_expr)), unname(coef(fit_ref)))
  expect_equal(unname(coef(fit_wrap)), unname(coef(fit_ref)))
})


# ============================================================================
# 2. Gaps and panels (pure R)
# ============================================================================

test_that("a gap in the time variable makes the lag NA and shrinks the sample", {
  gapped <- phillips[phillips$year != 1970, ]
  expect_warning(
    fit <- ivreg2(cinf ~ l(unem, 1), data = gapped, tvar = "year"),
    "gap"
  )
  # 48 physical rows; 1948 has no lag, and 1971 loses its lag to the gap
  expect_equal(nobs(fit), nrow(gapped) - 2L)
})

test_that("panel lags never cross unit boundaries and ignore row order", {
  set.seed(42)
  pd <- expand.grid(id = 1:3, t = 1:10)
  pd$x <- rnorm(30)
  pd$y <- pd$x + rnorm(30)
  pd <- pd[sample(nrow(pd)), ]
  fit <- ivreg2(y ~ l(x, 1), data = pd, tvar = "t", ivar = "id")
  expect_equal(nobs(fit), 27L)  # first period per unit dropped

  pd_sorted <- pd[order(pd$id, pd$t), ]
  pd_sorted$xl <- ave(pd_sorted$x, pd_sorted$id,
                      FUN = function(v) c(NA, head(v, -1)))
  fit_manual <- ivreg2(y ~ xl, data = pd_sorted)
  expect_equal(sort(unname(coef(fit))), sort(unname(coef(fit_manual))))
})

test_that("subset is applied after lag computation (Stata's if semantics)", {
  # Lags must come from the full data, including rows excluded by subset
  fit_sub <- ivreg2(cinf ~ l(unem, 1), data = phillips, tvar = "year",
                    subset = year >= 1960)
  ph <- phillips
  ph$unem_l1 <- c(NA, head(ph$unem, -1))
  fit_ref <- ivreg2(cinf ~ unem_l1, data = ph, subset = year >= 1960)
  expect_equal(unname(coef(fit_sub)), unname(coef(fit_ref)))
  # 1960 keeps its lag (1959 exists in the full data)
  expect_equal(nobs(fit_sub), sum(phillips$year >= 1960))
})


# ============================================================================
# 3. Validation errors (pure R)
# ============================================================================

test_that("operators without tvar error informatively", {
  expect_error(
    ivreg2(cinf ~ l(unem, 1), data = phillips),
    "require `tvar`"
  )
})

test_that("exported stubs error outside an ivreg2 formula", {
  expect_error(l(1:5), "inside an ivreg2\\(\\) formula")
  expect_error(d(1:5), "inside an ivreg2\\(\\) formula")
})

test_that("leads, non-integer and non-constant orders error", {
  expect_error(
    ivreg2(cinf ~ l(unem, -1), data = phillips, tvar = "year"),
    "leads"
  )
  expect_error(
    ivreg2(cinf ~ l(unem, 1.5), data = phillips, tvar = "year"),
    "integer-valued"
  )
  expect_error(
    ivreg2(cinf ~ l(unem, unem), data = phillips, tvar = "year"),
    "constant"
  )
})

test_that("nested operators and non-top-level ranges error", {
  expect_error(
    ivreg2(cinf ~ l(d(unem, 1), 1), data = phillips, tvar = "year"),
    "[Nn]ested"
  )
  expect_error(
    ivreg2(cinf ~ log(l(unem, 1:3)), data = phillips, tvar = "year"),
    "top-level"
  )
})

test_that("scalar lags work on the LHS; lag ranges there error", {
  fit <- ivreg2(l(cinf, 1) ~ unem, data = phillips, tvar = "year")
  # cinf is NA in 1948 (first difference of inflation), so l(cinf, 1) is
  # missing in both 1948 (no lag year) and 1949 (lag value is NA): N = 47
  expect_equal(nobs(fit), nrow(phillips) - 2L)
  expect_error(
    ivreg2(l(cinf, 1:2) ~ unem, data = phillips, tvar = "year"),
    "left-hand side"
  )
})

test_that("time values must be integer-valued and within 2^53", {
  # Beyond 2^53, t - k can round onto an observed timestamp and fabricate
  # lags (1e16 - 1 == 1e16 in doubles); fractional grids have the mirror
  # false-NA problem. Stata's tsset requires integer time values.
  set.seed(7)
  big <- data.frame(t = 1e16 + c(0, 2, 4, 6), x = rnorm(4), y = rnorm(4))
  expect_error(ivreg2(y ~ l(x, 1), data = big, tvar = "t"),
               "integer-valued")
  frac <- data.frame(t = c(0.5, 1.5, 2.5, 3.5), x = rnorm(4), y = rnorm(4))
  expect_error(ivreg2(y ~ l(x, 1), data = frac, tvar = "t"),
               "integer-valued")
})

test_that("epoch-microsecond panel timestamps lag exactly", {
  # Regression: plain paste() formats doubles at 15 significant digits, so
  # distinct timestamps near 1.7e15 (integer-valued, well inside 2^53)
  # collapsed to one key and produced wrong lags.
  pd <- data.frame(id = rep(1:2, each = 3), t = 1.7e15 + rep(0:2, 2),
                   x = c(10, 20, 30, 40, 50, 60))
  lagged <- ivreg2r:::.ts_lag_values(pd$x, 1, pd$t, pd$id)
  expect_equal(lagged, c(NA, 10, 20, NA, 40, 50))
  pd$y <- pd$x + rep(c(1, 2, 3), 2)
  fit <- ivreg2(y ~ l(x, 1), data = pd, tvar = "t", ivar = "id")
  expect_equal(nobs(fit), 4L)
})

test_that("the -2^53 endpoint is rejected; +2^53 is accepted", {
  # -2^53 - 1 rounds back to -2^53, so the lower endpoint would self-lag.
  endp <- data.frame(t = -2^53 + c(0, 1, 2), x = c(10, 20, 30),
                     y = c(1, 2, 3))
  expect_error(ivreg2(y ~ l(x, 1), data = endp, tvar = "t"),
               "integer-valued")
  # Operators only subtract nonnegative k, so the UPPER endpoint is safe:
  # at +2^53 every t - k is exactly representable.
  lag_hi <- ivreg2r:::.ts_lag_values(c(10, 20, 30), 1, 2^53 + c(-2, -1, 0))
  expect_equal(lag_hi, c(NA, 10, 20))
  # Need 4 rows: the lag drops one, and the fit requires N - K > 0 with K = 2.
  hi <- data.frame(t = 2^53 + c(-3, -2, -1, 0), x = c(10, 20, 30, 40),
                   y = c(1, 2, 3, 5))
  fit <- ivreg2(y ~ l(x, 1), data = hi, tvar = "t")
  expect_equal(nobs(fit), 3L)
})

test_that("large numeric panel IDs do not collide in lag keys", {
  # Regression: paste() formats numeric panel IDs at 15 significant digits,
  # collapsing distinct IDs near 1.7e15 and lagging across panels.
  pd <- data.frame(id = rep(1.7e15 + c(0, 1), each = 2),
                   t = rep(1:2, 2), x = c(1, 2, 3, 4))
  lagged <- ivreg2r:::.ts_lag_values(pd$x, 1, pd$t, pd$id)
  expect_equal(lagged, c(NA, 1, NA, 3))
})

test_that("infinite time values error (would self-match as their own lag)", {
  ph_inf <- phillips
  ph_inf$year[5] <- Inf
  expect_error(
    ivreg2(cinf ~ l(unem, 1), data = ph_inf, tvar = "year"),
    "finite"
  )
  # Same guard on the HAC/kernel time-index path
  expect_error(
    ivreg2(cinf ~ unem, data = ph_inf, tvar = "year",
           vcov = "HAC", kernel = "bartlett", bw = 2),
    "finite"
  )
})

test_that("repeated and missing time values error", {
  dup <- rbind(phillips, phillips[1, ])
  expect_error(
    ivreg2(cinf ~ l(unem, 1), data = dup, tvar = "year"),
    "repeated time values"
  )
  ph_na <- phillips
  ph_na$year[3] <- NA
  expect_error(
    ivreg2(cinf ~ l(unem, 1), data = ph_na, tvar = "year"),
    "contains NA"
  )
  set.seed(1)
  pd <- expand.grid(id = 1:2, t = 1:5)
  pd$x <- rnorm(10)
  pd$y <- rnorm(10)
  pd2 <- rbind(pd, pd[1, ])
  expect_error(
    ivreg2(y ~ l(x, 1), data = pd2, tvar = "t", ivar = "id"),
    "within panel"
  )
})

test_that("the same operator term in two formula parts is a duplicate", {
  expect_error(
    ivreg2(cinf ~ l(unem, 1) | unem | l(unem, 1) + l(unem, 2),
           data = phillips, tvar = "year"),
    "multiple formula parts"
  )
})

test_that("a variable and its lag may appear in different parts", {
  # unem endogenous, l(unem, k) instruments — the H83 pattern
  expect_silent(
    ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips, tvar = "year")
  )
})

test_that("partial cannot be combined with tvar/ivar as model variables", {
  ph <- phillips
  ph$trend <- ph$year
  expect_error(
    ivreg2(cinf ~ year + l(unem, 1), data = ph, tvar = "year",
           partial = "year"),
    "time variable"
  )
})


# ============================================================================
# 4. Options referencing operator terms (pure R)
# ============================================================================

test_that("orthog accepts operator names, with whitespace-insensitive matching", {
  fit_a <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                  tvar = "year", vcov = "robust", orthog = "l(unem, 1)")
  fit_b <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                  tvar = "year", vcov = "robust", orthog = "l(unem,1)")
  expect_equal(fit_a$diagnostics$orthog$stat, fit_b$diagnostics$orthog$stat)
  expect_equal(fit_a$diagnostics$orthog$df, 1L)
})

test_that("orthog expands operator ranges like the formula does", {
  fit_range <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                      tvar = "year", vcov = "robust",
                      orthog = "l(unem, 1:2)")
  fit_pair <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                     tvar = "year", vcov = "robust",
                     orthog = c("l(unem, 1)", "l(unem, 2)"))
  expect_equal(fit_range$diagnostics$orthog$stat,
               fit_pair$diagnostics$orthog$stat)
  expect_equal(fit_range$diagnostics$orthog$df, 2L)
})

test_that("redundant accepts operator names", {
  fit <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                tvar = "year", redundant = "l(unem, 3)")
  expect_false(is.null(fit$diagnostics$redundancy))
  expect_equal(fit$diagnostics$redundancy$df, 1L)
})

test_that("invalid operator names in options are still caught", {
  expect_error(
    ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
           tvar = "year", orthog = "l(unem, 4)"),
    "l\\(unem, 4\\)"
  )
})


# ============================================================================
# 5. predict() with ts operators (pure R)
# ============================================================================

test_that("predict on the estimation data reproduces fitted values", {
  fit <- ivreg2(cinf ~ l(unem, 1), data = phillips, tvar = "year")
  p <- predict(fit, newdata = phillips)
  # First row has no lag within newdata -> NA; rest match fitted
  expect_true(is.na(p[1]))
  expect_equal(unname(p[-1]), unname(fitted(fit)))
})

test_that("predict without history yields NA, with history yields values", {
  fit <- ivreg2(cinf ~ l(unem, 1), data = phillips, tvar = "year")
  p_no_hist <- predict(fit, newdata = phillips[c(1, 30), ])
  expect_true(all(is.na(p_no_hist)))
  p_hist <- predict(fit, newdata = phillips[29:30, ])
  expect_true(is.na(p_hist[1]))
  expect_false(is.na(p_hist[2]))
  full <- predict(fit, newdata = phillips)
  expect_equal(p_hist[2], full[30])
})

test_that("instrument-only lags impose no ts requirements on newdata", {
  # H83 pattern: lags only among the excluded instruments. Prediction
  # scores only the regressors, so newdata needs neither the time
  # variable nor lag history (Stata's predict xb parity).
  fit <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                tvar = "year")
  p <- predict(fit, newdata = data.frame(unem = 5))
  expect_equal(unname(p), unname(drop(c(1, 5) %*% coef(fit))))
  # Repeated time values in counterfactual scenarios are fine too
  p2 <- predict(fit, newdata = data.frame(unem = c(5, 6),
                                          year = c(1990, 1990)))
  expect_equal(length(p2), 2L)
  expect_false(anyNA(p2))
})

test_that("predict validates the ts context in newdata", {
  fit <- ivreg2(cinf ~ l(unem, 1), data = phillips, tvar = "year")
  nd <- phillips
  names(nd)[names(nd) == "year"] <- "yr"
  expect_error(predict(fit, newdata = nd), "not found in newdata")
})


