test_that("H83: AC IV with l(1/3).unem instruments matches Stata", {
  skip_if(!file.exists(fixture_path("tsop_phil_coef_ac_bw3.csv")),
          "ts-operator fixtures not found")
  fit <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                tvar = "year", vcov = "AC", kernel = "bartlett", bw = 3)
  expect_coef_fixture(fit, "tsop_phil_coef_ac_bw3.csv")
  expect_vcov_fixture(fit, "tsop_phil_vcov_ac_bw3.csv")
  dx <- read_diagnostics(fixture_path("tsop_phil_diagnostics_ac_bw3.csv"))
  expect_equal(nobs(fit), dx$N)
  expect_equal(fit$diagnostics$overid$stat, dx$j, tolerance = stata_tol$stat)
  expect_equal(fit$diagnostics$underid$stat, dx$idstat,
               tolerance = stata_tol$stat)
})

test_that("H84: GMM2S + AC Tukey-Hanning matches Stata", {
  skip_if(!file.exists(fixture_path("tsop_phil_coef_gmm2s_thann.csv")),
          "ts-operator fixtures not found")
  fit <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                tvar = "year", vcov = "AC", kernel = "thann", bw = 3,
                method = "gmm2s")
  expect_coef_fixture(fit, "tsop_phil_coef_gmm2s_thann.csv")
  expect_vcov_fixture(fit, "tsop_phil_vcov_gmm2s_thann.csv")
  dx <- read_diagnostics(fixture_path("tsop_phil_diagnostics_gmm2s_thann.csv"))
  expect_equal(nobs(fit), dx$N)
  expect_equal(fit$diagnostics$overid$stat, dx$j, tolerance = stata_tol$stat)
  # Restores the only sigma-under-gmm2s+HAC assertion, lost with the retired ts_gmm2s HAC cell.
  expect_equal(fit$sigma, dx$rmse, tolerance = stata_tol$coef)
})

test_that("H85: GMM2S + HAC QS + orthog(l1.unem) matches Stata", {
  skip_if(!file.exists(fixture_path("tsop_phil_coef_gmm2s_qs_orthog.csv")),
          "ts-operator fixtures not found")
  fit <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                tvar = "year", vcov = "HAC", kernel = "qs", bw = 3,
                method = "gmm2s", orthog = "l(unem, 1)")
  expect_coef_fixture(fit, "tsop_phil_coef_gmm2s_qs_orthog.csv")
  expect_vcov_fixture(fit, "tsop_phil_vcov_gmm2s_qs_orthog.csv")
  dx <- read_diagnostics(
    fixture_path("tsop_phil_diagnostics_gmm2s_qs_orthog.csv"))
  expect_equal(nobs(fit), dx$N)
  expect_equal(fit$diagnostics$overid$stat, dx$j, tolerance = stata_tol$stat)
  expect_equal(fit$diagnostics$orthog$stat, dx$cstat,
               tolerance = stata_tol$stat)
  expect_equal(fit$diagnostics$orthog$p, dx$cstatp, tolerance = stata_tol$pval)
  expect_equal(fit$diagnostics$orthog$df, dx$cstatdf)
})


