# 7. Stata fixtures: Klein H72-H76 (LIML family with L.profits / L.totinc)
# ============================================================================

test_that("H72: Klein LIML matches Stata", {
  fit <- ivreg2(klein_formula, data = klein, tvar = "yr", method = "liml")
  expect_coef_fixture(fit, "tsop_klein_coef_liml.csv")
  expect_vcov_fixture(fit, "tsop_klein_vcov_liml.csv")
  dx <- read_diagnostics(fixture_path("tsop_klein_diagnostics_liml.csv"))
  expect_equal(nobs(fit), dx$N)
  expect_equal(fit$lambda, dx$lambda, tolerance = stata_tol$stat)
  expect_equal(fit$kclass_value, dx$kclass, tolerance = stata_tol$stat)
  expect_equal(fit$diagnostics$anderson_rubin_overid$lr_stat, dx$arubin,
               tolerance = stata_tol$stat)
})

test_that("H73: Klein LIML + COVIV matches Stata", {
  fit <- ivreg2(klein_formula, data = klein, tvar = "yr", method = "liml",
                coviv = TRUE)
  expect_coef_fixture(fit, "tsop_klein_coef_liml_coviv.csv")
  expect_vcov_fixture(fit, "tsop_klein_vcov_liml_coviv.csv")
})

test_that("H74: Klein CUE equals Stata (and LIML, the help-file demo)", {
  # This cell carried a documented 1e-4 override ("klein N=21 CUE optimizer
  # noise", the H74 ruling) until the 2026-07-06 CUE closeout: parscale
  # scaling in the optimizer cut the noise to 1.2e-7 (coef) / 3.8e-9 (vcov),
  # so the override is retired and the cell runs at standard tolerances.
  fit_cue <- ivreg2(klein_formula, data = klein, tvar = "yr", method = "cue")
  expect_coef_fixture(fit_cue, "tsop_klein_coef_cue.csv")
  # The help file's point: CUE = LIML under iid + independence
  # (observed post-parscale agreement 1.7e-7 relative)
  fit_liml <- ivreg2(klein_formula, data = klein, tvar = "yr",
                     method = "liml")
  expect_equal(unname(coef(fit_cue)), unname(coef(fit_liml)),
               tolerance = 1e-6)
})

test_that("H75: Klein Fuller(1) matches Stata", {
  fit <- ivreg2(klein_formula, data = klein, tvar = "yr", method = "liml",
                fuller = 1)
  expect_coef_fixture(fit, "tsop_klein_coef_fuller1.csv")
  expect_vcov_fixture(fit, "tsop_klein_vcov_fuller1.csv")
  dx <- read_diagnostics(fixture_path("tsop_klein_diagnostics_fuller1.csv"))
  expect_equal(fit$kclass_value, dx$kclass, tolerance = stata_tol$stat)
})

test_that("H76: Klein kclass(1.19) matches Stata", {
  fit <- ivreg2(klein_formula, data = klein, tvar = "yr", method = "kclass",
                kclass = 1.19)
  expect_coef_fixture(fit, "tsop_klein_coef_kclass119.csv")
  expect_vcov_fixture(fit, "tsop_klein_vcov_kclass119.csv")
})


# ============================================================================
# 8. Stata fixture: abdata H88 (panel differences as instruments)
# ============================================================================

test_that("H88: GMM2S + cluster(id) with d./d2. instruments matches Stata", {
  fit <- ivreg2(n ~ 1 | w + k + ys |
                  d(w, 1) + d(k, 1) + d(ys, 1) +
                  d(w, 2) + d(k, 2) + d(ys, 2),
                data = abdata, tvar = "year", ivar = "id",
                method = "gmm2s", clusters = ~id)
  expect_coef_fixture(fit, "tsop_ab_coef_gmm2s_cl.csv")
  expect_vcov_fixture(fit, "tsop_ab_vcov_gmm2s_cl.csv")
  dx <- read_diagnostics(fixture_path("tsop_ab_diagnostics_gmm2s_cl.csv"))
  expect_equal(nobs(fit), dx$N)
  expect_equal(fit$n_clusters, dx$N_clust)
  expect_equal(fit$diagnostics$overid$stat, dx$j, tolerance = stata_tol$stat)
  expect_equal(fit$diagnostics$underid$stat, dx$idstat,
               tolerance = stata_tol$stat)
})

test_that("H88 sample: differences shrink the panel exactly as in Stata", {
  # d2 needs two consecutive prior periods within the unit
  fit <- ivreg2(n ~ d(w, 2), data = abdata, tvar = "year", ivar = "id")
  ab_sorted <- abdata[order(abdata$id, abdata$year), ]
  ab_sorted$d2w <- ave(ab_sorted$w, ab_sorted$id,
                       FUN = function(v) c(NA, NA, diff(diff(v))))
  fit_manual <- ivreg2(n ~ d2w, data = ab_sorted)
  expect_equal(nobs(fit), nobs(fit_manual))
  expect_equal(sort(unname(coef(fit))), sort(unname(coef(fit_manual))))
})


# ============================================================================
# 9. Broom / S3 integration
# ============================================================================

test_that("tidy() and glance() carry operator term labels", {
  fit <- ivreg2(cinf ~ 1 | unem | l(unem, 1:3), data = phillips,
                tvar = "year")
  td <- tidy(fit)
  expect_true("unem" %in% td$term)
  gl <- glance(fit)
  expect_equal(gl$nobs, nrow(phillips) - 3L)
})

test_that("update() refits a ts-operator model", {
  fit <- ivreg2(cinf ~ l(unem, 1), data = phillips, tvar = "year")
  fit2 <- update(fit, cinf ~ l(unem, 2))
  expect_equal(nobs(fit2), nrow(phillips) - 2L)
  expect_true("l(unem, 2)" %in% names(coef(fit2)))
})
